<?php// Start output buffering to prevent any accidental outputob_start();// Set error reportingerror_reporting(E_ALL);ini_set('display_errors', 0); // Don't display errors in JSON responsesession_start();// Clear any previous outputob_clean();require_once __DIR__ . '/access.php';header('Content-Type: application/json; charset=UTF-8');mb_internal_encoding('UTF-8');// Check if user is admin or manager using existing functionsif (!isAdmin() && !isManager()) {    http_response_code(403);    echo json_encode(['success' => false, 'message' => 'Nedostatečná oprávnění']);    exit;}$baseDir = getRoot('videos');$action = $_POST['action'] ?? '';// Ensure videos directory exists with proper permissionsif (!is_dir($baseDir)) {    if (!mkdir($baseDir, 0755, true)) {        echo json_encode(['success' => false, 'message' => 'Nepodařilo se vytvořit adresář videí']);        exit;    }}try {    switch ($action) {        case 'edit_video':            $folderName = $_POST['folder_name'] ?? '';            $oldFileName = $_POST['old_file_name'] ?? '';            $newVideoName = trim($_POST['new_video_name'] ?? '');            $videoDescription = trim($_POST['video_description'] ?? '');                        if (empty($folderName) || empty($oldFileName) || empty($newVideoName)) {                echo json_encode(['success' => false, 'message' => 'Chybí požadované parametry']);                exit;            }                        // Sanitize paths to prevent directory traversal            $folderName = basename($folderName);            $oldFileName = basename($oldFileName);                        $folderPath = $baseDir . $folderName . '/';            $oldFilePath = $folderPath . $oldFileName;                        if (!file_exists($oldFilePath)) {                echo json_encode(['success' => false, 'message' => 'Soubor nenalezen']);                exit;            }                        // Get file extension            $fileExtension = pathinfo($oldFileName, PATHINFO_EXTENSION);                        // Sanitize new name and preserve extension            $newVideoName = preg_replace('/[^a-zA-Z0-9áčďéěíňóřšťúůýžÁČĎÉĚÍŇÓŘŠŤÚŮÝŽ\-_.\s]/u', '', $newVideoName);            $newFileName = $newVideoName . '.' . $fileExtension;            $newFilePath = $folderPath . $newFileName;                        // Check if new filename already exists (and it's not the same file)            if (file_exists($newFilePath) && $oldFileName !== $newFileName) {                echo json_encode(['success' => false, 'message' => 'Soubor s tímto názvem již existuje']);                exit;            }                        // Rename file if name changed            $fileRenamed = true;            if ($oldFileName !== $newFileName) {                if (!rename($oldFilePath, $newFilePath)) {                    echo json_encode(['success' => false, 'message' => 'Nepodařilo se přejmenovat soubor']);                    exit;                }            }                        // Update metadata (descriptions)            $metadataFile = $folderPath . '.metadata.json';            $metadata = [];            if (file_exists($metadataFile)) {                $metadataContent = file_get_contents($metadataFile);                $metadata = json_decode($metadataContent, true) ?: [];            }                        if (!isset($metadata['descriptions'])) {                $metadata['descriptions'] = [];            }                        // Remove old description if file was renamed            if ($oldFileName !== $newFileName && isset($metadata['descriptions'][$oldFileName])) {                unset($metadata['descriptions'][$oldFileName]);            }                        // Update description            if (!empty($videoDescription)) {                $metadata['descriptions'][$newFileName] = $videoDescription;            } else {                // Remove description if empty                unset($metadata['descriptions'][$newFileName]);            }                        // Update metadata timestamp            $metadata['updated'] = date('Y-m-d H:i:s');                        // Save metadata            if (file_put_contents($metadataFile, json_encode($metadata, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE))) {                echo json_encode(['success' => true, 'message' => 'Video bylo úspěšně upraveno']);            } else {                echo json_encode(['success' => false, 'message' => 'Soubor byl přejmenován, ale nepodařilo se uložit popis']);            }            break;        case 'delete_video':            $folderName = $_POST['folder_name'] ?? '';            $fileName = $_POST['file_name'] ?? '';                        if (empty($folderName) || empty($fileName)) {                echo json_encode(['success' => false, 'message' => 'Chybí parametry']);                exit;            }                        // Sanitize paths to prevent directory traversal            $folderName = basename($folderName);            $fileName = basename($fileName);                        $folderPath = $baseDir . $folderName . '/';            $filePath = $folderPath . $fileName;                        if (!file_exists($filePath)) {                echo json_encode(['success' => false, 'message' => 'Soubor nenalezen']);                exit;            }                        if (!is_writable($filePath)) {                echo json_encode(['success' => false, 'message' => 'Nemáte oprávnění ke smazání tohoto souboru']);                exit;            }                        if (unlink($filePath)) {                // Also remove from metadata                $metadataFile = $folderPath . '.metadata.json';                if (file_exists($metadataFile)) {                    $metadata = json_decode(file_get_contents($metadataFile), true) ?: [];                    if (isset($metadata['descriptions'][$fileName])) {                        unset($metadata['descriptions'][$fileName]);                        $metadata['updated'] = date('Y-m-d H:i:s');                        file_put_contents($metadataFile, json_encode($metadata, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));                    }                }                echo json_encode(['success' => true, 'message' => 'Soubor byl smazán']);            } else {                echo json_encode(['success' => false, 'message' => 'Nepodařilo se smazat soubor']);            }            break;        case 'delete_folder':            $folderName = $_POST['folder_name'] ?? '';                        if (empty($folderName)) {                echo json_encode(['success' => false, 'message' => 'Chybí název složky']);                exit;            }                        // Sanitize path to prevent directory traversal            $folderName = basename($folderName);            $folderPath = $baseDir . $folderName . '/';                        if (!is_dir($folderPath)) {                echo json_encode(['success' => false, 'message' => 'Složka nenalezena']);                exit;            }                        if (!is_writable($folderPath)) {                echo json_encode(['success' => false, 'message' => 'Nemáte oprávnění ke smazání této složky']);                exit;            }                        // Delete all files in folder first            $files = array_diff(scandir($folderPath), ['.', '..']);            foreach ($files as $file) {                $filePath = $folderPath . $file;                if (is_file($filePath)) {                    if (!unlink($filePath)) {                        echo json_encode(['success' => false, 'message' => 'Nepodařilo se smazat soubor: ' . $file]);                        exit;                    }                }            }                        // Delete folder            if (rmdir($folderPath)) {                echo json_encode(['success' => true, 'message' => 'Složka byla smazána']);            } else {                echo json_encode(['success' => false, 'message' => 'Nepodařilo se smazat složku']);            }            break;        case 'rename_folder':            $oldName = $_POST['old_name'] ?? '';            $newName = trim($_POST['new_name'] ?? '');                        if (empty($oldName) || empty($newName)) {                echo json_encode(['success' => false, 'message' => 'Chybí názvy složek']);                exit;            }                        // Sanitize folder names            $oldName = basename($oldName);            $newName = preg_replace('/[^a-zA-Z0-9\s\-_áčďéěíňóřšťúůýžÁČĎÉĚÍŇÓŘŠŤÚŮÝŽ]/u', '', $newName);            $newName = trim($newName);                        if (empty($newName)) {                echo json_encode(['success' => false, 'message' => 'Nový název obsahuje nepovolené znaky']);                exit;            }                        $oldPath = $baseDir . $oldName . '/';            $newPath = $baseDir . $newName . '/';                        if (!is_dir($oldPath)) {                echo json_encode(['success' => false, 'message' => 'Původní složka nenalezena']);                exit;            }                        if (is_dir($newPath)) {                echo json_encode(['success' => false, 'message' => 'Složka s novým názvem již existuje']);                exit;            }                        if (!is_writable($oldPath)) {                echo json_encode(['success' => false, 'message' => 'Nemáte oprávnění k přejmenování této složky']);                exit;            }                        if (rename($oldPath, $newPath)) {                echo json_encode(['success' => true, 'message' => 'Složka byla přejmenována']);            } else {                echo json_encode(['success' => false, 'message' => 'Nepodařilo se přejmenovat složku']);            }            break;        default:            echo json_encode(['success' => false, 'message' => 'Neznámá akce: ' . $action]);            break;    }} catch (Exception $e) {    echo json_encode(['success' => false, 'message' => 'Chyba serveru: ' . $e->getMessage()]);}exit;?>